# Independent literal XML, not generated by the authoring engine or official catalog.
$script:NsModule=Import-Module (Join-Path $PSScriptRoot '../skills/hwp-skill/scripts/lib/HwpHwpxScopedEdit.psm1') -Force -PassThru
$script:NsPath=Join-Path $PSScriptRoot '../skills/hwp-skill/scripts/lib/HwpHwpxNoteSettings.ps1'
function New-NsFixture {
    $xml=[xml]::new();$xml.PreserveWhitespace=$true
    $xml.LoadXml(@'
<hs:sec xmlns:hs="http://www.hancom.co.kr/hwpml/2011/section" xmlns:hp="http://www.hancom.co.kr/hwpml/2011/paragraph" xmlns:v="urn:vendor"><hp:p id="1" paraPrIDRef="0"><hp:run charPrIDRef="7"><hp:secPr id="kept" textDirection="HORIZONTAL" v:section="opaque"><hp:grid lineGrid="0" charGrid="0" wonggojiFormat="0"/><hp:pagePr width="59528" height="84186" landscape="WIDELY"/><hp:footNotePr v:note="kept"><hp:autoNumFormat type="DIGIT" userChar="*" prefixChar="[" suffixChar="]" supscript="0" v:format="kept"><v:payload token="opaque"/></hp:autoNumFormat><hp:noteLine length="-1" type="SOLID" width="0.12 mm" color="#000000"/><hp:noteSpacing betweenNotes="283" belowLine="567" aboveLine="850"/><hp:numbering type="CONTINUOUS" newNum="1"/><hp:placement place="EACH_COLUMN" beneathText="0"/><v:extension keep="yes"/><!--keep note comment--></hp:footNotePr><hp:endNotePr><hp:autoNumFormat type="ROMAN_SMALL" userChar="" prefixChar="" suffixChar=")" supscript="1"/><hp:noteLine length="1234" type="DASH" width="0.2 mm" color="#121212"/><hp:noteSpacing betweenNotes="0" belowLine="100" aboveLine="200"/><hp:numbering type="ON_SECTION" newNum="3"/><hp:placement place="END_OF_DOCUMENT" beneathText="0"/></hp:endNotePr><v:sectionExtension/></hp:secPr><hp:ctrl><hp:colPr colCount="2"/></hp:ctrl><hp:t>unchanged</hp:t></hp:run></hp:p><hp:p id="2" paraPrIDRef="0"><hp:run charPrIDRef="8"><hp:t>body</hp:t></hp:run></hp:p></hs:sec>
'@)
    $sections=[Collections.Generic.List[string]]::new();$sections.Add('Contents/section0.xml')
    return @{Target=$xml.DocumentElement.FirstChild.FirstChild.FirstChild;Package=@{Sections=$sections;Xml=@{'Contents/section0.xml'=$xml}};Allocation=@{}}
}
function Get-NsNode($Node,[string]$Name){$Node.SelectSingleNode('.//*[local-name()="'+$Name+'"]')}
function New-NsOperation($Settings=@{numbering=@{newNum=2}},[string]$Kind='footnote'){@{type='set-note-settings';sectionIndex=0;kind=$Kind;settings=$Settings}}
function Invoke-NsSettings($F,$Op,$Budget=$F.Allocation){& $script:NsModule {param($T,$O,$P,$A,$Path) if(Test-Path -LiteralPath $Path){. $Path};New-ScopedNoteSettings $T $O $P $A} $F.Target $Op $F.Package $Budget $script:NsPath}
function Assert-NsFailure($F,$Op,[string]$Pattern='*'){
    $before=$F.Target.OwnerDocument.OuterXml;$allocation=ConvertTo-Json -InputObject $F.Allocation -Depth 10 -Compress
    $failure=$null;try{$null=Invoke-NsSettings $F $Op}catch{$failure=$_.Exception}
    ($null -ne $failure)|Should Be $true
    ($failure -is [Management.Automation.CommandNotFoundException])|Should Be $false
    $failure.Message|Should BeLike $Pattern
    [string]::Equals($before,$F.Target.OwnerDocument.OuterXml,[StringComparison]::Ordinal)|Should Be $true
    (ConvertTo-Json -InputObject $F.Allocation -Depth 10 -Compress)|Should BeExactly $allocation
}

Describe 'Private prepared note settings without native applications' {
    It 'returns a detached secPr clone and preserves omitted settings, opposite notes and source XML' {
        $f=New-NsFixture;$before=$f.Target.OwnerDocument.OuterXml
        $p=Invoke-NsSettings $f (New-NsOperation)
        $p -is [Xml.XmlElement]|Should Be $true;$p.LocalName|Should BeExactly 'secPr';($null -eq $p.ParentNode)|Should Be $true
        $p.GetAttribute('id')|Should BeExactly 'kept';$p.GetAttribute('section','urn:vendor')|Should BeExactly 'opaque'
        foreach($name in @('grid','pagePr','endNotePr','autoNumFormat','noteLine','noteSpacing','placement','sectionExtension')){(Get-NsNode $p $name).OuterXml|Should BeExactly (Get-NsNode $f.Target $name).OuterXml}
        (Get-NsNode (Get-NsNode $p 'footNotePr') 'numbering').GetAttribute('newNum')|Should BeExactly '2'
        $f.Target.OwnerDocument.OuterXml|Should BeExactly $before
    }
    It 'changes format attributes without flattening unknown metadata or userChar payload' {
        $f=New-NsFixture;$face=[char]::ConvertFromUtf32(0x1F600)
        $p=Invoke-NsSettings $f (New-NsOperation @{autoNumFormat=@{type='CIRCLED_DIGIT';prefixChar='<&'+$face;suffixChar='';supscript=$true}})
        $node=Get-NsNode $p 'autoNumFormat';$node.GetAttribute('type')|Should BeExactly 'CIRCLED_DIGIT';$node.GetAttribute('prefixChar')|Should BeExactly ('<&'+$face);$node.GetAttribute('suffixChar')|Should BeExactly '';$node.GetAttribute('supscript')|Should BeExactly '1'
        $node.GetAttribute('userChar')|Should BeExactly '*';$node.GetAttribute('format','urn:vendor')|Should BeExactly 'kept';$node.FirstChild.OuterXml|Should BeExactly '<v:payload token="opaque" xmlns:v="urn:vendor" />'
    }
    It 'supports every payload-free auto-number format in the declared subset' {
        foreach($type in @('DIGIT','CIRCLED_DIGIT','ROMAN_CAPITAL','ROMAN_SMALL','LATIN_CAPITAL','LATIN_SMALL','CIRCLED_LATIN_CAPITAL','CIRCLED_LATIN_SMALL','HANGUL_SYLLABLE','CIRCLED_HANGUL_SYLLABLE','HANGUL_JAMO','CIRCLED_HANGUL_JAMO','HANGUL_PHONETIC','IDEOGRAPH','CIRCLED_IDEOGRAPH','DECAGON_CIRCLE','DECAGON_CIRCLE_HANJA','2DIGIT')){
            $p=Invoke-NsSettings (New-NsFixture) (New-NsOperation @{autoNumFormat=@{type=$type}});(Get-NsNode $p 'autoNumFormat').GetAttribute('type')|Should BeExactly $type
        }
    }
    It 'blocks new IMAGE USER_CHAR and symbol formats without guessing payloads' {
        foreach($type in @('IMAGE','USER_CHAR','SYMBOL','SYMBOL2')){Assert-NsFailure (New-NsFixture) (New-NsOperation @{autoNumFormat=@{type=$type}}) '*enum*'}
        Assert-NsFailure (New-NsFixture) (New-NsOperation @{autoNumFormat=@{userChar='x'}}) '*Unrecognized*'
    }
    It 'converts note spacing millimeters to integer HWPUNIT and preserves omitted spacing' {
        $f=New-NsFixture;$p=Invoke-NsSettings $f (New-NsOperation @{noteSpacing=@{betweenNotesMm=25.4;belowLineMm=0;aboveLineMm=12.7}})
        $n=Get-NsNode $p 'noteSpacing';$n.GetAttribute('betweenNotes')|Should BeExactly '7200';$n.GetAttribute('belowLine')|Should BeExactly '0';$n.GetAttribute('aboveLine')|Should BeExactly '3600'
        $p=Invoke-NsSettings $f (New-NsOperation @{noteSpacing=@{belowLineMm=1}});$n=Get-NsNode $p 'noteSpacing';$n.GetAttribute('belowLine')|Should BeExactly '283';$n.GetAttribute('aboveLine')|Should BeExactly '850'
    }
    It 'assigns exact reference-test spacing and preserves unusual stored endnote line lengths' {
        foreach($kind in @('footnote','endnote')){
            $f=New-NsFixture;$end=Get-NsNode $f.Target 'endNotePr';(Get-NsNode $end 'noteLine').SetAttribute('length','14692344')
            $p=Invoke-NsSettings $f (New-NsOperation @{noteSpacing=@{betweenNotesMm=2.54;belowLineMm=1.27}} $kind)
            $selected=Get-NsNode $p $(if($kind -eq 'footnote'){'footNotePr'}else{'endNotePr'});$spacing=Get-NsNode $selected 'noteSpacing'
            $spacing.GetAttribute('betweenNotes')|Should BeExactly '720';$spacing.GetAttribute('belowLine')|Should BeExactly '360'
            (Get-NsNode (Get-NsNode $p 'endNotePr') 'noteLine').GetAttribute('length')|Should BeExactly '14692344'
            $p=Invoke-NsSettings $f (New-NsOperation @{noteLine=@{color='#112233'}} 'endnote')
            (Get-NsNode (Get-NsNode $p 'endNotePr') 'noteLine').GetAttribute('length')|Should BeExactly '14692344'
        }
    }
    It 'supports footnote restarts and placements without changing the endnote definition' {
        foreach($value in @('CONTINUOUS','ON_SECTION','ON_PAGE')){$p=Invoke-NsSettings (New-NsFixture) (New-NsOperation @{numbering=@{type=$value;newNum=[long]4294967295}});$n=Get-NsNode $p 'numbering';$n.GetAttribute('type')|Should BeExactly $value;$n.GetAttribute('newNum')|Should BeExactly '4294967295'}
        foreach($value in @('EACH_COLUMN','MERGED_COLUMN','RIGHT_MOST_COLUMN')){$p=Invoke-NsSettings (New-NsFixture) (New-NsOperation @{placement=@{place=$value;beneathText=$true}});$n=Get-NsNode $p 'placement';$n.GetAttribute('place')|Should BeExactly $value;$n.GetAttribute('beneathText')|Should BeExactly '1'}
    }
    It 'uses distinct endnote restart and placement enums and preserves omitted beneathText' {
        $f=New-NsFixture;$foot=(Get-NsNode $f.Target 'footNotePr').OuterXml
        foreach($value in @('CONTINUOUS','ON_SECTION')){foreach($place in @('END_OF_DOCUMENT','END_OF_SECTION')){
            $p=Invoke-NsSettings $f (New-NsOperation @{numbering=@{type=$value;newNum=9};placement=@{place=$place}} 'endnote')
            (Get-NsNode $p 'footNotePr').OuterXml|Should BeExactly $foot;$end=Get-NsNode $p 'endNotePr'
            (Get-NsNode $end 'numbering').GetAttribute('type')|Should BeExactly $value;(Get-NsNode $end 'placement').GetAttribute('place')|Should BeExactly $place;(Get-NsNode $end 'placement').GetAttribute('beneathText')|Should BeExactly '0'
        }}
        Assert-NsFailure $f (New-NsOperation @{placement=@{beneathText=$true}} 'endnote') '*Unrecognized*'
        Assert-NsFailure $f (New-NsOperation @{numbering=@{type='ON_PAGE'}} 'endnote') '*enum*'
        Assert-NsFailure $f (New-NsOperation @{placement=@{place='EACH_COLUMN'}} 'endnote') '*enum*'
    }
    It 'writes official line type names, thickness strings, RGB color and fixed HWPUNIT length' {
        $p=Invoke-NsSettings (New-NsFixture) (New-NsOperation @{noteLine=@{type='SLIM_THICK';widthMm=1;color='#aB12eF';lengthMm=25.4}})
        $n=Get-NsNode $p 'noteLine';$n.GetAttribute('type')|Should BeExactly 'SLIM_THICK';$n.GetAttribute('width')|Should BeExactly '1.0 mm';$n.GetAttribute('color')|Should BeExactly '#aB12eF';$n.GetAttribute('length')|Should BeExactly '7200'
        $p=Invoke-NsSettings (New-NsFixture) (New-NsOperation @{noteLine=@{color='#ABCDEF'}});(Get-NsNode $p 'noteLine').GetAttribute('length')|Should BeExactly '-1'
    }
    It 'accepts only the exact official note-line width and type enum values' {
        foreach($pair in @(@(0.1,'0.1 mm'),@(0.12,'0.12 mm'),@(0.15,'0.15 mm'),@(0.2,'0.2 mm'),@(0.25,'0.25 mm'),@(0.3,'0.3 mm'),@(0.4,'0.4 mm'),@(0.5,'0.5 mm'),@(0.6,'0.6 mm'),@(0.7,'0.7 mm'),@(1,'1.0 mm'),@(1.5,'1.5 mm'),@(2,'2.0 mm'),@(3,'3.0 mm'),@(4,'4.0 mm'),@(5,'5.0 mm'))){$p=Invoke-NsSettings (New-NsFixture) (New-NsOperation @{noteLine=@{widthMm=$pair[0]}});(Get-NsNode $p 'noteLine').GetAttribute('width')|Should BeExactly $pair[1]}
        foreach($type in @('NONE','SOLID','DOT','DASH','DASH_DOT','DASH_DOT_DOT','LONG_DASH','CIRCLE','DOUBLE_SLIM','SLIM_THICK','THICK_SLIM','SLIM_THICK_SLIM','WAVE','DOUBLEWAVE','THICK3D','THICKREV3D','3D','REV3D')){$p=Invoke-NsSettings (New-NsFixture) (New-NsOperation @{noteLine=@{type=$type}});(Get-NsNode $p 'noteLine').GetAttribute('type')|Should BeExactly $type}
    }
    It 'rejects unverified fullWidth semantics and invalid line settings atomically' {
        foreach($fields in @(@{fullWidth=$true},@{fullWidth=$false;lengthMm=1},@{widthMm=0.13},@{type='THIN_THICK'},@{color='red'},@{color="#123456`n"},@{lengthMm=-1})){Assert-NsFailure (New-NsFixture) (New-NsOperation @{noteLine=$fields})}
    }
    It 'retains unknown attributes and children on every changed leaf and note wrapper' {
        $f=New-NsFixture;$note=Get-NsNode $f.Target 'footNotePr'
        foreach($name in @('noteSpacing','numbering','placement','noteLine')){$n=Get-NsNode $note $name;$n.SetAttribute('opaque','urn:vendor','yes')|Out-Null;$null=$n.AppendChild($n.OwnerDocument.CreateComment('kept'))}
        $p=Invoke-NsSettings $f (New-NsOperation @{noteSpacing=@{aboveLineMm=1};numbering=@{newNum=4};placement=@{beneathText=$true};noteLine=@{lengthMm=10}})
        $n=Get-NsNode $p 'footNotePr';$n.GetAttribute('note','urn:vendor')|Should BeExactly 'kept'
        foreach($name in @('noteSpacing','numbering','placement','noteLine')){$leaf=Get-NsNode $n $name;$leaf.GetAttribute('opaque','urn:vendor')|Should BeExactly 'yes';$leaf.LastChild.OuterXml|Should BeExactly '<!--kept-->'}
        (Get-NsNode $n 'extension').GetAttribute('keep')|Should BeExactly 'yes'
    }
    It 'requires the selected existing note definition and edited child to be unique' {
        foreach($name in @('footNotePr','numbering')){
            $f=New-NsFixture;$n=Get-NsNode $f.Target $name;$null=$n.ParentNode.AppendChild($n.CloneNode($true));Assert-NsFailure $f (New-NsOperation) '*Ambiguous*'
            $f=New-NsFixture;$n=Get-NsNode $f.Target $name;$null=$n.ParentNode.RemoveChild($n);Assert-NsFailure $f (New-NsOperation) '*missing*'
        }
    }
    It 'rejects wrong section identity, detached or nested targets and multiple secPr definitions' {
        $f=New-NsFixture;$op=New-NsOperation;$op.sectionIndex=1;Assert-NsFailure $f $op '*section*'
        $f=New-NsFixture;$f.Target=$f.Target.CloneNode($true);Assert-NsFailure $f (New-NsOperation) '*target*'
        $f=New-NsFixture;$null=$f.Target.ParentNode.AppendChild($f.Target.CloneNode($true));Assert-NsFailure $f (New-NsOperation) '*secPr*'
        $f=New-NsFixture;$run=$f.Target.ParentNode;$wrapper=$run.OwnerDocument.CreateElement('hp','ctrl',$run.NamespaceURI);$null=$wrapper.AppendChild($f.Target);$null=$run.AppendChild($wrapper);Assert-NsFailure $f (New-NsOperation) '*secPr*'
    }
    It 'rejects unknown keys, empty settings or groups, and missing operation fields' {
        Assert-NsFailure (New-NsFixture) (New-NsOperation @{}) '*empty*'
        foreach($group in @('autoNumFormat','noteSpacing','numbering','placement','noteLine')){Assert-NsFailure (New-NsFixture) (New-NsOperation @{$group=@{}}) '*empty*';Assert-NsFailure (New-NsFixture) (New-NsOperation @{$group=@{bogus=1}}) '*Unrecognized*'}
        foreach($key in @('type','sectionIndex','kind','settings')){$op=New-NsOperation;$op.Remove($key);Assert-NsFailure (New-NsFixture) $op '*Missing*'}
        $op=New-NsOperation;$op.extra=1;Assert-NsFailure (New-NsFixture) $op '*Unrecognized*'
        $op=New-NsOperation;$op.type='set-section-settings';Assert-NsFailure (New-NsFixture) $op '*type*'
        foreach($kind in @('FOOTNOTE','other','')){Assert-NsFailure (New-NsFixture) (New-NsOperation @{numbering=@{newNum=2}} $kind) '*kind*'}
    }
    It 'rejects coerced numbers, invalid Boolean values, NaN infinity and out-of-range units' {
        foreach($value in @(0,-1,[long]4294967296,'2',$true,1.5,$null)){Assert-NsFailure (New-NsFixture) (New-NsOperation @{numbering=@{newNum=$value}}) '*newNum*'}
        foreach($value in @('true',0,1,$null)){Assert-NsFailure (New-NsFixture) (New-NsOperation @{autoNumFormat=@{supscript=$value}}) '*Boolean*';Assert-NsFailure (New-NsFixture) (New-NsOperation @{placement=@{beneathText=$value}}) '*Boolean*'}
        foreach($value in @(-1,2001,'1',$false,[double]::NaN,[double]::PositiveInfinity,$null)){Assert-NsFailure (New-NsFixture) (New-NsOperation @{noteSpacing=@{belowLineMm=$value}})}
    }
    It 'rejects invalid XML and UTF16 and caps each prefix and suffix at 256 units' {
        foreach($key in @('prefixChar','suffixChar')){foreach($value in @([string][char]0,[string][char]0xD800,[string][char]0xDC00,42,('x'*257))){Assert-NsFailure (New-NsFixture) (New-NsOperation @{autoNumFormat=@{$key=$value}})}}
    }
    It 'uses ordinal keys enums and stored protection or Boolean flags' {
        Assert-NsFailure (New-NsFixture) (New-NsOperation @{numbering=@{type=('ON_PAGE'+[char]0x200B)}}) '*enum*'
        Assert-NsFailure (New-NsFixture) (New-NsOperation @{numbering=@{('newNum'+[char]0x200B)=2}}) '*Unrecognized*'
        $f=New-NsFixture;(Get-NsNode $f.Target 'autoNumFormat').SetAttribute('supscript',('false'+[char]0x200B));Assert-NsFailure $f (New-NsOperation @{autoNumFormat=@{prefixChar='x'}}) '*Boolean*'
        $f=New-NsFixture;$f.Target.ParentNode.SetAttribute('lock',('false'+[char]0x200B));Assert-NsFailure $f (New-NsOperation) '*Protected*'
    }
    It 'rejects protection on ancestors, selected notes or touched leaves without changing allocation' {
        foreach($name in @('secPr','footNotePr','numbering')){$f=New-NsFixture;$n=if($name -eq 'secPr'){$f.Target}else{Get-NsNode $f.Target $name};$n.SetAttribute('protect','1');Assert-NsFailure $f (New-NsOperation) '*Protected*'}
        $f=New-NsFixture;$f.Target.ParentNode.ParentNode.SetAttribute('editable','maybe');Assert-NsFailure $f (New-NsOperation) '*Protected*'
    }
    It 'keeps the original DOM and allocation intact after a later settings validation fails' {
        Assert-NsFailure (New-NsFixture) (New-NsOperation @{autoNumFormat=@{prefixChar='new'};noteLine=@{widthMm=0.13}})
        $f=New-NsFixture;$before=$f.Target.OwnerDocument.OuterXml;$staged=[Collections.Generic.List[object]]::new();$scratch=@{};$failed=$false
        try{foreach($op in @((New-NsOperation),(New-NsOperation @{placement=@{place='INVALID'}}))){$staged.Add((Invoke-NsSettings $f $op $scratch))}}catch{$failed=$true}
        $failed|Should Be $true;$staged.Count|Should Be 1;$f.Allocation.Count|Should Be 0;$f.Target.OwnerDocument.OuterXml|Should BeExactly $before
    }
    It 'bounds cumulative prepared XML and tracks successful clone allocation only' {
        $f=New-NsFixture;$p=Invoke-NsSettings $f (New-NsOperation);$f.Allocation.NoteSettingsPreparedCharacters|Should Be $p.OuterXml.Length
        $f=New-NsFixture;$f.Allocation.NoteSettingsPreparedCharacters=[long](16MB);Assert-NsFailure $f (New-NsOperation) '*16 MiB*'
        $f=New-NsFixture;$f.Allocation.NoteSettingsPreparedCharacters=-1;Assert-NsFailure $f (New-NsOperation) '*budget*'
    }
    It 'bounds subtree depth and node count before cloning unknown metadata' {
        $f=New-NsFixture;$extension=Get-NsNode $f.Target 'extension';$extension.InnerXml=('<v:n xmlns:v="urn:vendor">'*65)+('</v:n>'*65);Assert-NsFailure $f (New-NsOperation) '*depth 64*'
        $f=New-NsFixture;$fragment=$f.Target.OwnerDocument.CreateDocumentFragment();$fragment.InnerXml='<!--x-->'*65536;$null=$f.Target.AppendChild($fragment);Assert-NsFailure $f (New-NsOperation) '*65536*'
    }
}
